INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6538123', 'course-bili-season-6538123', '100001', '0', 'BILI-WRK-TEGUQK', 'course-category-workplace', 'instructor-bili-385047828', '从不敢举手到对答如流：斯坦福教授的即兴表达系统。', '95 讲完整课程 · 15 小时 55 分钟', '你是否在被突然点名发言时大脑一片空白？在社交场合自我介绍时尴尬到脚趾抠地？斯坦福大学讲师马特·亚伯拉罕用14年时间研究出一套即兴表达方法论，现已成为斯坦福商学院新生必修内容。本视频深度拆解这套六步系统：如何驯服焦虑的症状', '课程简介：你是否在被突然点名发言时大脑一片空白？在社交场合自我介绍时尴尬到脚趾抠地？斯坦福大学讲师马特·亚伯拉罕用14年时间研究出一套即兴表达方法论，现已成为斯坦福商学院新生必修内容。本视频深度拆解这套六步系统：如何驯服焦虑的症状和根源、为什么追求平庸反而能达到卓越、如何把威胁重构为机会、深度倾听的节奏空间恩典法则、以及最实用的即兴表达结构框架。掌握这套系统，你就能在任何场合想得更快、说得更聪明。课程结构：共 1 章 95 讲，累计时长 15 小时 55 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/32e61736a2fee2c964396adbc1fdcae17e4e241d.jpg', '["职场技能","沟通表达","职业发展","从不敢举手到对答如流"]', 57337, 95, 10181, '4.6', 3418, 'BV16cZQBdE5d', NULL, NULL, NULL, 1, 0, 'standard', NULL, '认知便利店M', 0, 'tenant', 'published', '2026-02-18T23:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
