INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ta4y1g7ts', 'course-bili-bv1ta4y1g7ts', '100001', '0', 'BILI-WRK-USFNFS', 'course-category-workplace', 'instructor-bili-3493259068311944', '精品课程 ｜ 俞敏洪 领导力原则', '7 讲完整课程 · 1 小时 43 分钟', '网络 1、个性原则：主动积极、合群友好、开朗坦诚、果断坚毅 以兄弟，导师的角色存在 2、分享原则：情感分享、知识分享、成就分享、利益分享 小时候给同村人分糖的故事，为创建新东方带来灵感，有难同当有福同享是一件无比重', '课程简介：网络 1、个性原则：主动积极、合群友好、开朗坦诚、果断坚毅 以兄弟，导师的角色存在 2、分享原则：情感分享、知识分享、成就分享、利益分享 小时候给同村人分糖的故事，为创建新东方带来灵感，有难同当有福同享是一件无比重要的事情 3、主导原则：主动出手、抓住先机、寻找伙伴、扩大战果 打造核心团队，如果让大家觉得只有你一个人在领导这个团队，那么团队的力量就无法爆发出来，只能孤军奋战，需要对核心人员无比信任。4、气场原则：避开高压、自创气场、提升高度、反败为胜 知道自己的弱点，在避开自己的弱点。5、愿景原则：清楚使命、明确愿景、坚定信念、激励成员 6、目标原则：战略制定、分解步骤、目标衔接、战术跟上 术的层面永远解决不到真正的问题 7、判断原则：广泛调研、充分讨论、遵从常识、灵活纠偏 团队需要保持高度一致性 8、纠错原则：机制监控、交流坦诚、自我批评、及时改正。新东方7人常委会，4票以上决定策略是否执行，如果一个公司敢指出领导的错误，并且领导也愿意接受和改正，那么这个公司犯错误的概率就会变低。让自我批评以调侃的形式说出来更容易接受，并形成这样的氛围 9、奖励原则：私下批评，公开奖励、虚实并重、频次得当 核心团队每个月得到一次鼓励，员工怕老板把他们忘了。10、人才原则：长期战友、短期利交、用人之长、警惕分裂 备用人才和自己一条线 11、团队原则：价值一致、能力多样、跨代 课程结构：共 1 章 7 讲，累计时长 1 小时 43 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/7ed8b97b319d78146dc9a5d5bf504561dcaa4b55.png', '["职场技能","沟通表达","职业发展","精品课程","俞敏洪","领导力原则"]', 6233, 7, 27936, '4.4', 8171, 'BV1ta4y1G7tS', NULL, NULL, NULL, 1, 0, 'standard', NULL, '知识财富学院', 0, 'tenant', 'published', '2023-05-01T16:08:46.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
