INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1omwdzcedg', 'course-bili-bv1omwdzcedg', '100001', '0', 'BILI-WRK-Y1S1RG', 'course-category-workplace', 'instructor-bili-267090770', '百万经理秘籍：私教管理课程，打造高效健身团队', '16 讲完整课程 · 10 小时 55 分钟', '🌟 想要成为健身行业的顶尖管理者？我们为你带来百万经理亲授的私教管理课程，带你掌握私教管理的黄金法则，打造顶级健身团队！💪 无论你是健身新手，还是希望提升管理技能的私教经理，这个视频都将为你提供最实用的指导。', '课程简介：🌟 想要成为健身行业的顶尖管理者？我们为你带来百万经理亲授的私教管理课程，带你掌握私教管理的黄金法则，打造顶级健身团队！💪 无论你是健身新手，还是希望提升管理技能的私教经理，这个视频都将为你提供最实用的指导。跟随我们的课程，学会如何通过科学的管理方法，打造高效的健身团队，实现职业突破！快来一起学习，让管理更科学，团队更高效！课程结构：共 2 章 16 讲，累计时长 10 小时 55 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/840669b34df710ebdae3eb6d72ae92ba80cf3f08.jpg', '["职场技能","沟通表达","职业发展","百万经理秘籍","私教管理课程","打造高效健身团队"]', 39309, 16, 106, '4.5', 12, 'BV1omWdzcEdG', NULL, NULL, NULL, 1, 0, 'standard', NULL, '健身piupiu', 0, 'tenant', 'published', '2025-10-21T13:17:46.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
