INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv19v4y1u7sd', 'course-bili-bv19v4y1u7sd', '100001', '0', 'BILI-WRK-LSG4QV', 'course-category-workplace', 'instructor-bili-7332127', '清华大学老师带你学习人人都能听懂的项目管理课程，干货！！！', '12 讲完整课程 · 1 小时 30 分钟', '杨述老师：清华大学国际工程项目管理研究院主任，企业家俱乐部秘书长，多年来从事项目管理课题开发、培训及PMP试题分析和研究工作，为企业培养了大批项目管理实战人才。不仅剖析PMBOK的知识框架和内容，更能将理论运用于实', '课程简介：杨述老师：清华大学国际工程项目管理研究院主任，企业家俱乐部秘书长，多年来从事项目管理课题开发、培训及PMP试题分析和研究工作，为企业培养了大批项目管理实战人才。不仅剖析PMBOK的知识框架和内容，更能将理论运用于实践。杨教授主讲的《项目管理体验式培训》系列课程同样受到众多企业的青睐。课程结构：共 2 章 12 讲，累计时长 1 小时 30 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/4f4ff089dd1ba63789db34b252d75ad0c6d5006f.png', '["职场技能","沟通表达","职业发展","项目管理","干货！！！"]', 5431, 12, 3265, '4.3', 649, 'BV19v4y1u7sD', NULL, NULL, NULL, 1, 0, 'standard', NULL, '知识大魔王', 0, 'tenant', 'published', '2022-06-12T04:43:09.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
