INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1f9bcbsepo', 'course-bili-bv1f9bcbsepo', '100001', '0', 'BILI-WRK-Z2YYGJ', 'course-category-workplace', 'instructor-bili-3546580418300292', '发挥领导力：基础原则（Exercising Leadership: Foundational Principles)【全集】', '6 讲完整课程 · 1 小时 44 分钟', '我们这个时代的危机给我们的家庭、组织、社区和社会带来了巨大的适应挑战。需要能够动员人们应对这些挑战并改善生活的领导层是至关重要的。在这个入门课程中，您将探索在一个不断变化的世界中领导的策略，在这个世界中，适应性压力将继', '课程简介：我们这个时代的危机给我们的家庭、组织、社区和社会带来了巨大的适应挑战。需要能够动员人们应对这些挑战并改善生活的领导层是至关重要的。在这个入门课程中，您将探索在一个不断变化的世界中领导的策略，在这个世界中，适应性压力将继续挑战我们所有人。您将发现接近复杂组织系统的新方法，并对我们所有人都面临的工作采取深思熟虑的行动。最重要的是，您将反思如何在您最关心的领导挑战中向前迈进。课程分为四个部分。您将探索领导力的定义，并应用一个流程来学习它。在第1节和第2节中，您将实施诊断方法，以更好地了解工作和权限。在第3节中，您将考虑采取行动的策略。在第4节和结论中，您将反思您在变化的世界中生存和茁壮成长的个人策略。课程结构：共 1 章 6 讲，累计时长 1 小时 44 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/70242d37bf11926d94689422e8dda247c10b4ea0.jpg', '["职场技能","沟通表达","职业发展","哈佛大学","发挥领导力","基础原则"]', 6290, 6, 1001, '4.5', 675, 'BV1F9BCBSEpo', NULL, NULL, NULL, 1, 0, 'standard', NULL, '天和中国', 0, 'tenant', 'published', '2025-12-27T12:43:44.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
